        'aa000000-0000-0000-0000-000000000002',
        'Varanasi North', 'vidhan_sabha', 'UP/65')
ON CONFLICT DO NOTHING;

-- Booths — derive distinct booths from staging data
-- We use a deterministic UUID built from the booth_number so that
-- subsequent objects can reference it without a second lookup.
SELECT
    -- Deterministic UUID from booth_number: b001 → ...0042, b002 → ...0043, etc.
    ('aa000001-0000-0000-0000-' || LPAD(s.booth_number::TEXT, 12, '0'))::UUID,
    'aa000000-0000-0000-0000-000000000003',
    s.booth_number::VARCHAR,
    'Booth ' || s.booth_number || ' – ' || MIN(SPLIT_PART(s.address, ', ', 3)),
    MIN(SPLIT_PART(s.address, ', ', 3)) || ', Varanasi'
FROM voter_staging s
GROUP BY s.booth_number
ON CONFLICT DO NOTHING;

-- Streets — derive distinct street + booth combinations
SELECT
    gen_random_uuid(),
    ('aa000001-0000-0000-0000-' || LPAD(s.booth_number::TEXT, 12, '0'))::UUID,
    s.street,
    COUNT(*)
FROM voter_staging s
GROUP BY s.booth_number, s.street
ON CONFLICT DO NOTHING;


-- ─────────────────────────────────────────────────────────────────
-- STEP 4: voters_eci  (ECI source-of-truth, READ ONLY layer)
-- ─────────────────────────────────────────────────────────────────

    id,
    epic_number,
    name,
    dob,
    gender,
    phone,
    address,
    booth_id,
    street_id,
    serial_number,
    imported_at
)
SELECT
    s.id::UUID,
    s.epic_number,
    s.name,
    s.dob::DATE,
    -- Gender: source uses M / F / O — all valid in gender_type enum
    CASE s.gender
        WHEN 'M' THEN 'M'::gender_type
        WHEN 'F' THEN 'F'::gender_type
        ELSE          'O'::gender_type
    END,
    -- Phone: source column was INT so no leading zeros lost; cast to varchar
    s.phone::VARCHAR,
    s.address,
    -- Booth FK
    ('aa000001-0000-0000-0000-' || LPAD(s.booth_number::TEXT, 12, '0'))::UUID,
    -- Street FK: find the matching street in this booth
    (SELECT st.id
     FROM streets st
     WHERE st.booth_id = ('aa000001-0000-0000-0000-' || LPAD(s.booth_number::TEXT, 12, '0'))::UUID
       AND st.name = s.street
     LIMIT 1),
    -- serial_number within each booth (for eci_part_number compatibility)
    ROW_NUMBER() OVER (PARTITION BY s.booth_number ORDER BY s.epic_number)::INTEGER,
    now()
FROM voter_staging s
ON CONFLICT (epic_number) DO NOTHING;


-- ─────────────────────────────────────────────────────────────────
-- STEP 5: voters  (operational / AI segmentation layer)
-- ─────────────────────────────────────────────────────────────────

    id,
    eci_voter_id,
    segment,
    is_key_voter,
    occupation,
    education,
    family_size,
    notif_sms,
    notif_whatsapp,
    notif_push,
    aadhaar_verified,
    preferred_language,
    citizen_portal_active
)
SELECT
    ve.id,
    ve.id,
    -- ── Segment mapping ──────────────────────────────────────────
    -- The production schema voter_segment ENUM has:
    --   farmer | youth | women | businessman | senior | govt_employee | other
    -- Source data also has 'trader' and 'daily_wage' which must be remapped.
    CASE s.segment
        WHEN 'farmer'        THEN 'farmer'::voter_segment
        WHEN 'youth'         THEN 'youth'::voter_segment
        WHEN 'women'         THEN 'women'::voter_segment
        WHEN 'businessman'   THEN 'businessman'::voter_segment
        WHEN 'senior'        THEN 'senior'::voter_segment
        WHEN 'govt_employee' THEN 'govt_employee'::voter_segment
        WHEN 'trader'        THEN 'businessman'::voter_segment
        WHEN 'daily_wage'    THEN 'other'::voter_segment
        ELSE                      'other'::voter_segment
    END,
    -- ── Boolean fields ───────────────────────────────────────────
    -- Source stores 'True' / 'False' as strings, cast to real booleans.
    (s.is_key_voter    = 'True'),
    s.occupation,
    s.education,
    s.family_size,
    -- Notification defaults
    true,   -- notif_sms
    false,  -- notif_whatsapp
    false,  -- notif_push
    (s.aadhaar_verified = 'True'),
    s.preferred_language,
    false   -- citizen_portal_active  (one voter flagged below for demo)
FROM voter_staging s
JOIN voters_eci ve ON ve.id = s.id::UUID
ON CONFLICT (eci_voter_id) DO NOTHING;


-- ── Demo voter: activate citizen portal for the fixed ID used in the app ──────
-- This ensures the DEMO_VOTER_ID (00000000...0001) is active.
UPDATE voters
SET citizen_portal_active = true,
    notif_push            = true
WHERE id = '00000000-0000-0000-0000-000000000001'::UUID;


