-- ─────────────────────────────────────────────────────────────────
-- STEP 7: voter_scheme_status
-- Assign schemes intelligently based on voter segment.
-- ─────────────────────────────────────────────────────────────────

-- PM-KISAN → all farmers
SELECT v.id, '00001001-0000-0000-0000-000000000001'::UUID, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'farmer'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- PMFBY (crop insurance) → farmers
SELECT v.id, '00001001-0000-0000-0000-000000000004'::UUID, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'farmer'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- Ujjwala Yojana → women segment
SELECT v.id, '00001001-0000-0000-0000-000000000003'::UUID, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'women'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- BBBP → women segment
SELECT v.id, '00001001-0000-0000-0000-000000000007'::UUID, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'women'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- PMMVY → women segment
SELECT v.id, '00001001-0000-0000-0000-000000000010'::UUID, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'women'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- MUDRA → businessmen (traders mapped to businessman)
SELECT v.id, '00001001-0000-0000-0000-000000000008'::UUID, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'businessman'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- APY → senior citizens (enrolled + converted)
SELECT v.id, '00001001-0000-0000-0000-000000000005'::UUID,
       'enrolled'::scheme_voter_status, now() - interval '8 months', true, true
FROM voters v
WHERE v.segment = 'senior'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- PMVVY → senior citizens
SELECT v.id, '00001001-0000-0000-0000-000000000009'::UUID, 'eligible'::scheme_voter_status, false
FROM voters v
WHERE v.segment = 'senior'
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- PM Jan Dhan → everyone (first 300 enrolled, rest eligible)
SELECT
    v.id,
    '00001001-0000-0000-0000-000000000006'::UUID,
    CASE WHEN ROW_NUMBER() OVER (ORDER BY v.created_at) <= 300 THEN 'enrolled'::scheme_voter_status ELSE 'eligible'::scheme_voter_status END,
    CASE WHEN ROW_NUMBER() OVER (ORDER BY v.created_at) <= 300 THEN now() - interval '1 year' ELSE NULL END,
    true,
    CASE WHEN ROW_NUMBER() OVER (ORDER BY v.created_at) <= 300 THEN true ELSE false END
FROM voters v
ON CONFLICT (voter_id, scheme_id) DO NOTHING;

-- PM Awas → key voters + large families as applied
SELECT v.id, '00001001-0000-0000-0000-000000000002'::UUID, 'applied'::scheme_voter_status, true
FROM voters v
WHERE v.is_key_voter = true OR v.family_size >= 6
ON CONFLICT (voter_id, scheme_id) DO NOTHING;


